mapper.select:
SELECT FROM tool_catalog
status = #{status}
ORDER BY tool_code, id

mapper.update:
UPDATE tool_catalog
SET status = #{status},
    lock_version = lock_version + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE tool_catalog
SET lock_version = lock_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND lock_version = #{expectedLockVersion}
  AND status != 'DISABLED'

UPDATE tool_catalog
SET published_version_id = #{versionId},
    status = 'PUBLISHED',
    lock_version = lock_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND lock_version = #{expectedLockVersion}
  AND status != 'DISABLED'
